/* Horizonte authoring acceptance against the real local report-gen UI.
 * Creates only disposable projects. PDF input must already be generated by report-gen.
 * Functional observations are explicitly automated, not human visual approval.
 */
'use strict';
const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');
const assert = require('node:assert/strict');
const {spawn, execFileSync} = require('node:child_process');
const {createHash} = require('node:crypto');
const {isDeepStrictEqual} = require('node:util');
const {chromium} = require('playwright');

const root = path.resolve(__dirname, '..');
const args = process.argv.slice(2);
const opt = (key, fallback) => args.includes(key) ? args[args.indexOf(key) + 1] : fallback;
const python = process.env.RG_PYTHON || 'python3';
const out = path.resolve(opt('--output', 'out/horizonte-authoring'));
const slug = opt('--slug', 'horizonte-authoring');
const bundle = opt('--bundle');
const projectDir = opt('--project-dir');
const pdf = opt('--pdf');
assert.match(slug, /^[a-z0-9][a-z0-9-]{0,63}$/, 'Use a bounded synthetic project slug');
for (const [flag, value] of [['--bundle', bundle], ['--pdf', pdf]]) {
  assert.ok(value && fs.statSync(value).isFile(), flag + ' must name an existing input file');
}
assert.ok(projectDir && fs.statSync(path.join(projectDir, 'engagement.yaml')).isFile(),
  '--project-dir must name the original fictional project directory');
assert.ok(fs.statSync(pdf).size <= 16 * 1024 * 1024, 'Native PDF viewer supports at most 16 MiB');
assert.equal(fs.readFileSync(pdf).subarray(0, 5).toString(), '%PDF-', 'Input is a PDF');
fs.mkdirSync(out, {recursive: true});
assert.ok(!fs.existsSync(path.join(out, 'results.json')), 'Use a fresh results directory');
const hash = value => createHash('sha256').update(value).digest('hex');
const fileHash = file => hash(fs.readFileSync(file));
function directoryHashes(directory, prefix = '') {
  return Object.fromEntries(fs.readdirSync(directory, {withFileTypes: true})
    .sort((a, b) => a.name.localeCompare(b.name)).flatMap(entry => {
      const relative = prefix + entry.name;
      const absolute = path.join(directory, entry.name);
      assert.ok(!entry.isSymbolicLink(), 'Input tree contains no symbolic links');
      return entry.isDirectory() ? Object.entries(directoryHashes(absolute, relative + '/')) :
        [[relative, fileHash(absolute)]];
    }));
}
const sources = [
  'scripts/audit-horizonte-authoring.cjs', 'scripts/browser-server-0211.py',
  'webapp/static/app.js', 'webapp/static/insights.js', 'webapp/static/design-library.js',
  'webapp/design_api.py', 'webapp/visual_api.py', 'visual_review.py',
];
const sourceHashes = () => Object.fromEntries(sources.map(name => [name, fileHash(path.join(root, name))]));
const inputHashes = () => ({bundle: fileHash(bundle), pdf: fileHash(pdf), project: directoryHashes(projectDir)});
const results = {
  schema: 'report-gen-horizonte-authoring/1', started: new Date().toISOString(),
  checks: [], screens: [], downloads: [], rasters: [], pageErrors: [], apiErrors: [], externalRequests: [],
  input: {bundle: path.resolve(bundle), pdf: path.resolve(pdf), project_dir: path.resolve(projectDir)},
  inputStart: inputHashes(), sourceStart: sourceHashes(), coverage: [],
  limits: [
    'Only report-gen generated the supplied banking report; this harness generates no report artifacts.',
    'The auxiliary enterprise project exercises creation; its starter text is not the banking report.',
    'Opening and decoding two actual PDF pages exercises the viewer, not a visual review of every page.',
    'The downloaded observation is an automated functional record, not human approval or an asserted visual defect.',
    'The PDF hash identifies the supplied bytes; linking an uploaded PDF to a revision does not prove its producer.',
    'No Microsoft Word verification, automatic layout approval, or PDF comparison is claimed.',
  ],
};
const save = () => fs.writeFileSync(path.join(out, 'results.json'), JSON.stringify(results, null, 2) + '\n');
function check(name, passed, detail) {
  results.checks.push({name, passed: !!passed, ...(detail === undefined ? {} : {detail})});
  save();
  assert.ok(passed, name + (detail === undefined ? '' : ': ' + JSON.stringify(detail)));
  console.log('PASS ' + name);
}
const clean = page => page.waitForFunction(() => typeof S !== 'undefined' &&
  !projectStore.loading && !projectBusyCount && !projectStore.dirty && !projectStore.saving &&
  !document.querySelector('#splash'), null, {timeout: 60000});
const data = page => page.evaluate(() => JSON.parse(JSON.stringify(S.data)));
const savedState = page => page.evaluate(() => ({data: JSON.parse(JSON.stringify(S.data)), etag: projectStore.etag}));
async function expose(page, selector) {
  const target = page.locator(selector).first();
  const ancestors = await target.evaluate(el => {
    let d = el.parentElement?.closest('details');
    const list = [];
    while (d) { if (!d.open) list.unshift(d.id || null); d = d.parentElement?.closest('details'); }
    return list;
  });
  for (const id of ancestors) {
    assert.ok(id, 'Menu disclosure has a stable ID');
    await page.locator('#' + id + ' > summary').click();
  }
  return target;
}
async function click(page, selector) { await (await expose(page, selector)).click(); }
async function screen(page, name, target) {
  await page.evaluate(() => document.fonts.ready);
  if (target) await target.scrollIntoViewIfNeeded();
  const file = path.join(out, name + '.png');
  await page.screenshot({path: file, fullPage: false});
  results.screens.push({name, path: file, sha256: fileHash(file), viewport: page.viewportSize()});
  save();
}
async function importBundle(page) {
  page.once('dialog', dialog => dialog.accept(slug));
  const chooser = page.waitForEvent('filechooser');
  await click(page, '#importProjectBtn');
  await (await chooser).setFiles(bundle);
  await page.waitForFunction(value => S.slug === value && !projectStore.loading && !projectBusyCount,
    slug, {timeout: 60000});
  await clean(page);
}
async function moveSection(page, key, position) {
  await click(page, '#navReport');
  await click(page, '[data-section-move="' + key + '"]');
  const dialog = page.locator('dialog.experience-dialog[open]');
  await dialog.locator('[data-section-position]').fill(String(position));
  await dialog.locator('[data-section-move-apply]').click();
  await dialog.waitFor({state: 'detached'});
  await clean(page);
}
const sectionKeys = project => project.report.sections.map(section => section.key);
async function sidebarKeys(page) {
  return page.locator('#sectionList [data-section-move]').evaluateAll(nodes => nodes.map(n => n.dataset.sectionMove));
}
async function saveRaster(response, number) {
  check('Native viewer page ' + number + ' returns actual PNG bytes',
    response.ok() && /image\/png/.test(response.headers()['content-type'] || ''));
  const bytes = await response.body();
  check('Native viewer page ' + number + ' carries the PNG signature',
    bytes.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10])));
  const file = path.join(out, 'native-viewer-page-' + number + '.png');
  fs.writeFileSync(file, bytes);
  results.rasters.push({page: number, path: file, sha256: hash(bytes), size: bytes.length});
  save();
}

let server, browser, page, startupTimer;
async function stopServer() {
  if (!server || server.exitCode !== null || server.signalCode !== null) return;
  await new Promise(resolve => {
    const timer = setTimeout(() => { server.kill('SIGKILL'); resolve(); }, 5000);
    server.once('exit', () => { clearTimeout(timer); resolve(); });
    server.kill('SIGTERM');
  });
}
const workspace = fs.mkdtempSync(path.join(os.tmpdir(), 'report-gen-acceptance-0211-horizonte-'));
fs.writeFileSync(path.join(workspace, '.test-only'), 'synthetic acceptance workspace');

(async () => {
  try {
    server = spawn(python, [path.join(root, 'scripts/browser-server-0211.py'), '--workspace', workspace],
      {cwd: root, env: process.env});
    server.stderr.on('data', part => fs.appendFileSync(path.join(out, 'server.log'), part));
    const base = await new Promise((resolve, reject) => {
      let stdout = '';
      startupTimer = setTimeout(() => reject(Error('Server startup timeout')), 60000);
      server.stdout.on('data', part => {
        stdout += part;
        for (const line of stdout.split('\n')) {
          try { const value = JSON.parse(line); if (value.url) { clearTimeout(startupTimer); resolve(value.url); } }
          catch { /* The server URL is a complete JSON line. */ }
        }
      });
      server.once('error', reject);
      server.once('exit', code => reject(Error('Server exited: ' + code)));
    });
    const executable = opt('--executable', process.env.RG_CHROMIUM_EXECUTABLE || process.env.REPORT_GEN_CHROMIUM);
    browser = await chromium.launch({headless: true, ...(executable ? {executablePath: executable} : {})});
    results.browser = browser.version();
    const context = await browser.newContext({viewport: {width: 1440, height: 1000}, reducedMotion: 'reduce', acceptDownloads: true});
    await context.route('**/*', route => {
      const url = route.request().url();
      if (/^https?:/.test(url) && new URL(url).origin !== new URL(base).origin) {
        results.externalRequests.push(url); return route.abort();
      }
      return route.continue();
    });
    await context.addInitScript(() => {
      localStorage.setItem('rg.uiLang', 'es'); localStorage.setItem('rg.previewVisible', '0');
    });
    page = await context.newPage();
    page.on('pageerror', error => { results.pageErrors.push(String(error)); save(); });
    page.on('response', response => {
      if (response.status() >= 400 && new URL(response.url()).pathname.startsWith('/api/')) {
        results.apiErrors.push({method: response.request().method(), url: response.url().replace(base, ''), status: response.status()}); save();
      }
    });
    const initial = await page.goto(base);
    await clean(page);
    check('Real isolated editor serves its Content Security Policy', !!initial.headers()['content-security-policy']);

    // Creation starts from the actual gallery and persists a new enterprise project.
    const auxiliary = slug + '-enterprise';
    await click(page, '#newProjectBtn');
    const gallery = page.locator('dialog.design-dialog[open]');
    await gallery.waitFor();
    const categories = gallery.locator('[data-design-category-select]');
    if (await categories.isVisible()) await categories.selectOption('corporate');
    else await gallery.locator('[data-design-category="corporate"]').click();
    await gallery.locator('[data-design="enterprise-control-review"]').click();
    await gallery.locator('[data-design-variant]').selectOption('quiet');
    await gallery.locator('[data-design-sample-language]').selectOption('es');
    await screen(page, '01-enterprise-gallery');
    await gallery.getByRole('button', {name: 'Continuar con esta plantilla', exact: true}).click();
    await page.locator('#newModal[open]').waitFor();
    const title = 'Aceptación ficticia Horizonte — autoría empresarial';
    const client = 'Banco Horizonte Austral — proyecto auxiliar ficticio';
    await page.locator('#mTitle').fill(title);
    await page.locator('#mClient').fill(client);
    await page.locator('#mSlug').fill(auxiliary);
    check('Enterprise creation discloses the selected profile and its own structure',
      await page.locator('#mPresetOptions').isHidden() &&
      (await page.locator('#mDesignSelected').innerText()).includes('Revisión de controles'));
    await screen(page, '02-enterprise-creation-details');
    const creation = page.waitForResponse(r => r.request().method() === 'POST' &&
      new URL(r.url()).pathname === '/api/design-library/projects');
    await page.locator('#mCreate').click();
    const createdResponse = await creation;
    check('Enterprise project is created through the native project API', createdResponse.status() === 200);
    await page.waitForFunction(value => S.slug === value, auxiliary, {timeout: 60000});
    await clean(page);
    const created = await savedState(page);
    const meta = created.data.meta;
    check('New enterprise project retains the explicit profile, variant, language and entered details',
      meta.design?.id === 'enterprise-control-review' && meta.design?.variant === 'quiet' &&
      meta.design?.layout === 'editorial' && meta.lang === 'es' && meta.report_title === title &&
      meta.client === client && created.data.report.sections.length > 0);
    await page.reload(); await clean(page);
    check('New enterprise project survives a real reload with exact data and revision',
      isDeepStrictEqual(await savedState(page), created));
    results.enterprise = {slug: auxiliary, profile: meta.design, section_keys: sectionKeys(created.data), etag: created.etag};
    await screen(page, '03-enterprise-project-saved');
    results.coverage.push({area: 'Enterprise project creation', mode: 'UI', details: 'Gallery → explicit quiet variant and Spanish → new project → exact persisted data and revision after reload.'});

    // All bank mutations occur only in an isolated native backup import.
    await importBundle(page);
    const expected = JSON.parse(execFileSync(python, ['-c',
      'import json,yaml,sys;print(json.dumps(yaml.safe_load(open(sys.argv[1], encoding="utf-8"))))',
      path.join(projectDir, 'engagement.yaml')], {encoding: 'utf8', maxBuffer: 8 * 1024 * 1024}));
    const baseline = await data(page);
    check('Native backup import exactly preserves the original banking project', isDeepStrictEqual(baseline, expected));
    const key = 'bha-control-matrix';
    const originalKeys = sectionKeys(baseline);
    const originalPosition = originalKeys.indexOf(key) + 1;
    check('Banking case contains the independently authored control matrix section', originalPosition > 2);
    const reordered = structuredClone(baseline);
    const [section] = reordered.report.sections.splice(originalPosition - 1, 1);
    reordered.report.sections.splice(1, 0, section);
    const originalETag = (await savedState(page)).etag;
    await moveSection(page, key, 2);
    const moved = await savedState(page);
    check('Section control moves only the requested section, preserving all authored content',
      isDeepStrictEqual(moved.data, reordered) && moved.etag !== originalETag &&
      isDeepStrictEqual(await sidebarKeys(page), sectionKeys(reordered)));
    await page.reload(); await clean(page);
    check('Reordered sections persist across a real reload', isDeepStrictEqual(await savedState(page), moved));
    await click(page, '#navReport');
    await screen(page, '04-banking-sections-reordered', await expose(page, '[data-section-move="' + key + '"]'));
    await moveSection(page, key, originalPosition);
    await page.reload(); await clean(page);
    check('Restoring the original section order restores the entire original banking project',
      isDeepStrictEqual(await data(page), baseline) && isDeepStrictEqual(await sidebarKeys(page), originalKeys));
    results.section_order = {key, before: originalKeys, moved: sectionKeys(reordered), restored: sectionKeys(await data(page))};
    results.coverage.push({area: 'Section ordering', mode: 'UI', details: 'Move custom control matrix to position 2, reload and compare every project field; restore its original position through the same controls and reload again.'});

    // This is the own-PDF viewer, deliberately separate from the PDF comparison UI.
    const beforeViewer = await savedState(page);
    const linkedRevision = beforeViewer.etag.replace(/^W\//, '').replace(/^"|"$/g, '');
    await click(page, '#insightsBtn');
    await page.locator('[data-insights-tab="visual"]').click();
    const visual = page.locator('[data-insights-content="visual"]');
    await visual.getByText('Revisar PDF descargado de destinatario', {exact: true}).click();
    await visual.locator('[data-insights-field="visual-file"]').setInputFiles(pdf);
    const upload = page.waitForResponse(r => r.request().method() === 'POST' &&
      new URL(r.url()).pathname === '/api/projects/' + slug + '/visual');
    const firstRaster = page.waitForResponse(r => /^\/api\/visual\/[^/]+\/page\/1$/.test(new URL(r.url()).pathname));
    await visual.locator('[data-insights-action="visual-upload"]').click();
    const uploaded = await upload;
    check('Own PDF viewer accepts the supplied report-gen PDF', uploaded.status() === 200);
    const metadata = await uploaded.json();
    check('Own PDF viewer binds the exact input bytes and declares uploaded origin without Word or manual certification',
      metadata.pdf_sha256 === results.inputStart.pdf && metadata.origin === 'uploaded' &&
      metadata.revision === linkedRevision && metadata.original_word_verified === false &&
      metadata.manually_verified === false && metadata.pages.length >= 2);
    const image = visual.locator('.insights-pdf-preview img');
    await image.waitFor();
    await image.evaluate(node => node.decode());
    // Metadata rounds scaled points; PyMuPDF encloses pixels, differing by at most one.
    check('First actual PDF page decodes within one pixel of the viewer dimensions', await image.evaluate((node, expectedPage) =>
      node.alt === 'Página real 1' && node.naturalWidth > 0 && node.naturalHeight > 0 &&
      Math.abs(node.naturalWidth - expectedPage.width) <= 1 &&
      Math.abs(node.naturalHeight - expectedPage.height) <= 1 &&
      new URL(node.src).pathname === expectedPage.image_url, metadata.pages[0]));
    check('Native page navigation starts at the first page',
      await visual.locator('[data-insights-action="visual-previous"]').isDisabled() &&
      !await visual.locator('[data-insights-action="visual-next"]').isDisabled());
    await saveRaster(await firstRaster, 1);
    await screen(page, '05-native-pdf-page-1', image);
    const secondRaster = page.waitForResponse(r => new URL(r.url()).pathname === metadata.pages[1].image_url);
    await visual.locator('[data-insights-action="visual-next"]').click();
    await image.evaluate(node => node.decode());
    check('Visible Next control decodes the second actual PDF page', await image.evaluate((node, expectedPage) =>
      node.alt === 'Página real 2' && node.naturalWidth > 0 && node.naturalHeight > 0 &&
      Math.abs(node.naturalWidth - expectedPage.width) <= 1 &&
      Math.abs(node.naturalHeight - expectedPage.height) <= 1 &&
      new URL(node.src).pathname === expectedPage.image_url, metadata.pages[1]));
    await saveRaster(await secondRaster, 2);
    await screen(page, '06-native-pdf-page-2', image);
    await visual.locator('[data-insights-action="visual-previous"]').click();
    await image.evaluate(node => node.decode());
    check('Visible Previous control returns to the actual first page', await image.getAttribute('alt') === 'Página real 1');

    const author = 'Agente automatizado — aceptación Horizonte';
    const observations = [
      {number: 1, issue: 'other', note: 'Control funcional automatizado: página 1 abierta y raster decodificado. No se atribuye un defecto visual ni aprobación humana.'},
      {number: 2, issue: 'other', note: 'Control funcional automatizado: navegación a página 2 y regreso comprobados. Este registro no acredita revisión visual humana ni revisión de todas las páginas.'},
    ];
    for (const observation of observations) {
      await visual.locator('select[data-insights-field="number"]').selectOption(String(observation.number));
      await visual.locator('select[data-insights-field="issue"]').selectOption(observation.issue);
      await visual.getByLabel('Descripción del problema', {exact: true}).fill(observation.note);
      await visual.locator('[data-insights-action="add-visual-issue"]').click();
    }
    check('Native observation controls retain both explicitly automated annotations',
      await visual.locator('[data-insights-action="remove-visual-issue"]').count() === observations.length);
    const note = 'Ejercicio funcional automatizado y ficticio del visor propio. Se usa la opción de observaciones para probar su registro; no se afirma un defecto visual ni se concede aceptación visual manual. Identidad y método no verificados. PDF aportado desde una exportación de report-gen; su asociación a esta revisión no prueba su procedencia. No es aprobación humana.';
    await visual.getByLabel('Autor (declaración local)', {exact: true}).fill(author);
    await visual.locator('select[data-insights-field="decision"]').selectOption('issues');
    await visual.getByLabel('Nota general', {exact: true}).fill(note);
    await screen(page, '07-native-pdf-functional-observations', visual.locator('[data-insights-action="record-visual-review"]'));
    const reviewResponse = page.waitForResponse(r => r.request().method() === 'POST' &&
      new URL(r.url()).pathname === '/api/visual/' + metadata.id + '/review');
    await visual.locator('[data-insights-action="record-visual-review"]').click();
    const reviewed = await reviewResponse;
    check('Native observation form saves its record successfully', reviewed.status() === 200);
    const record = await reviewed.json();
    check('Record preserves exact source hash, revision, automated author and explicit observations',
      record.pdf_sha256 === results.inputStart.pdf && record.revision === linkedRevision &&
      record.author === author && record.note === note && record.decision === 'issues' &&
      isDeepStrictEqual(record.pages, observations));
    check('Record does not certify human identity, human review, Word execution or automatic layout correctness',
      record.author_identity === 'local_self_declaration' && record.original_word_verified === false &&
      record.automated_layout_verification === false && /self-declared/i.test(record.statement) &&
      /unverified/i.test(record.statement) && !record.statement.includes('Human review of this exact PDF'));
    const waiting = page.waitForEvent('download');
    await visual.locator('[data-insights-action="download-visual-review"]').click();
    const downloaded = await waiting;
    const recordFile = path.join(out, 'horizonte-native-visual-review.json');
    await downloaded.saveAs(recordFile);
    check('Native JSON download succeeds and exactly matches the server record',
      await downloaded.failure() === null && isDeepStrictEqual(JSON.parse(fs.readFileSync(recordFile, 'utf8')), record));
    results.downloads.push({name: path.basename(recordFile), path: recordFile, kind: 'native own-PDF observation record', sha256: fileHash(recordFile), size: fs.statSync(recordFile).size});
    await visual.getByText('Registro guardado', {exact: true}).click();
    await screen(page, '08-native-pdf-record-saved', visual.getByText('Registro guardado', {exact: true}));
    const stored = await page.evaluate(id => api.get('/api/visual/' + id), metadata.id);
    check('Native stored metadata retains the downloaded record without certifying manual verification',
      isDeepStrictEqual(stored.review, record) && stored.manually_verified === false && stored.original_word_verified === false);
    await clean(page);
    check('Own PDF viewer and observation record leave exact banking data and revision unchanged',
      isDeepStrictEqual(await savedState(page), beforeViewer));
    results.visual = {id: metadata.id, pdf_sha256: metadata.pdf_sha256, linked_revision: metadata.revision,
      origin: metadata.origin, total_pages: metadata.pages.length, opened_pages: [1, 2], record,
      provenance_limit: 'Uploaded PDF association does not independently verify its source revision.'};
    results.coverage.push({area: 'Own PDF viewer and observation JSON', mode: 'UI', details: 'Upload actual report-gen PDF, verify its hash, open pages 1 and 2, navigate back, add two explicitly automated observations and download the native JSON. No comparison viewer used.'});

    results.inputEnd = inputHashes(); results.sourceEnd = sourceHashes();
    check('Original bank inputs, native backup and supplied PDF remain byte-identical', isDeepStrictEqual(results.inputStart, results.inputEnd));
    check('Relevant report-gen sources remain unchanged during the run', isDeepStrictEqual(results.sourceStart, results.sourceEnd));
    check('No browser application errors occurred', results.pageErrors.length === 0, results.pageErrors);
    check('No unexpected API errors occurred', results.apiErrors.length === 0, results.apiErrors);
    check('No external requests occurred', results.externalRequests.length === 0, results.externalRequests);
    results.passed = true; results.finished = new Date().toISOString(); save();
    console.log('PASS ' + results.checks.length + ' Horizonte authoring checks');
  } catch (error) {
    results.passed = false; results.failure = String(error.stack || error); save();
    if (page && !page.isClosed()) await page.screenshot({path: path.join(out, 'failure.png')}).catch(() => {});
    console.error(error); process.exitCode = 1;
  } finally {
    clearTimeout(startupTimer);
    await browser?.close();
    await stopServer();
    fs.rmSync(workspace, {recursive: true, force: true});
  }
})();
